public String sortString(String s) {
    if (s == null || s.length() == 0) {
        return s;
    }

    int[] count = new int[26];
    for (char c : s.toCharArray()) {
        count[c - 'a']++;
    }

    StringBuilder result = new StringBuilder();
    int length = s.length();

    while (result.length() < length) {
        // Pick the smallest character greater than the last appended character
        for (int i = 0; i < 26; i++) {
            if (count[i] > 0) {
                result.append((char) (i + 'a'));
                count[i]--;
            }
        }

        // Pick the largest character smaller than the last appended character
        for (int i = 25; i >= 0; i--) {
            if (count[i] > 0) {
                result.append((char) (i + 'a'));
                count[i]--;
            }
        }
    }

    return result.toString();
}

public boolean splitArraySameAverage(int[] nums) {
    if (nums == null || nums.length < 2) {
        return false;
    }

    int totalSum = 0;
    for (int num : nums) {
        totalSum += num;
    }

    int n = nums.length;
    boolean[][][] dp = new boolean[n + 1][n / 2 + 1][totalSum + 1];
    dp[0][0][0] = true;

    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= n / 2; j++) {
            for (int k = 0; k <= totalSum; k++) {
                dp[i][j][k] = dp[i - 1][j][k];
                int current = nums[i - 1];
                if (k >= current) {
                    dp[i][j][k] |= dp[i - 1][j - 1][k - current];
                }
            }
        }
    }

    for (int j = 1; j <= n / 2; j++) {
        if (totalSum * j % n == 0 && dp[n][j][totalSum * j / n]) {
            return true;
        }
    }

    return false;
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null || cost.length < 2) {
        throw new IllegalArgumentException("Cost array must contain at least two steps.");
    }

    int n = cost.length;
    int[] dp = new int[n];
    dp[0] = cost[0];
    dp[1] = cost[1];

    for (int i = 2; i < n; i++) {
        dp[i] = cost[i] + Math.min(dp[i - 1], dp[i - 2]);
    }

    return Math.min(dp[n - 1], dp[n - 2]);
}

