public int maxAbsoluteSum(int[] nums) {
    if (nums == null || nums.length == 0) {
        throw new IllegalArgumentException("Array must not be null or empty");
    }

    int maxSum = 0;
    int minSum = 0;
    int currentMax = 0;
    int currentMin = 0;

    for (int num : nums) {
        currentMax = Math.max(0, currentMax + num);
        maxSum = Math.max(maxSum, currentMax);

