}

public static boolean isPowerOfTwo(int n) {
    if (n <= 0) {
        return false;
    }
    return (n & (n - 1)) == 0;
}

public static int addDigits(int num) {
    if (num < 0) {
        throw new IllegalArgumentException("The number should be non-negative.");
    }
    while (num >= 10) {
        int sum = 0;
        while (num > 0) {
            sum += num % 10;
            num /= 10;
        }
        num = sum;
    }
    return num;
}

public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0) {
        return 0;
    }

    int m = mat.length;
    int n = mat[0].length;
    int maxLength = 0;

    // Arrays to store the lengths of lines ending at each cell
    int[][] horizontal = new int[m][n];
    int[][] vertical = new int[m][n];
    int[][] diagonal = new int[m][n];
    int[][] antiDiagonal = new int[m][n];

    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                // Horizontal line
                horizontal[i][j] = (j > 0 ? horizontal[i][j - 1] : 0) + 1;
                // Vertical line
                vertical[i][j] = (i > 0 ? vertical[i - 1][j] : 0) + 1;
                // Diagonal line
                diagonal[i][j] = (i > 0 && j > 0 ? diagonal[i - 1][j - 1] : 0) + 1;
                // Anti-diagonal line
                antiDiagonal[i][j] = (i > 0 && j < n - 1 ? antiDiagonal[i - 1][j + 1] : 0) + 1;

                // Update the maximum length found
                maxLength = Math.max(maxLength, horizontal[i][j]);
                maxLength = Math.max(maxLength, vertical[i][j]);
                maxLength = Math.max(maxLength, diagonal[i][j]);
                maxLength = Math.max(maxLength, antiDiagonal[i][j]);
            }
        }
    }

    return maxLength;
}

public static String addThousandSeparator(int n) {
    if (n == 0) {
        return "0";
    }

    StringBuilder result = new StringBuilder();
    int count = 0;

    while (n > 0) {
        int digit = n % 10;
        result.append(digit);
        count++;
        n /= 10;

        if (count % 3 == 0 && n > 0) {
            result.append('.');
        }
    }

    return result.reverse().toString();
}

public static int squarePermutations(int[] A) {
    if (A == null || A.length == 0) return 0;

    boolean[] used = new boolean[A.length];
    int[] count = {0};
    backtrack(A, used, new int[A.length], 0, count);
    return count[0];
}

private static void backtrack(int[] A, boolean[] used, int[] temp, int level, int[] count) {
    if (level == A.length) {
        count[0]++;
        return;
    }

    for (int i = 0; i < A.length; i++) {
        if (used[i] || (i > 0 && A[i] == A[i - 1] && !used[i - 1])) continue;

        if (level == 0 || isPerfectSquare(temp[level - 1] + A[i])) {
            used[i] = true;
            temp[level] = A[i];
            backtrack(A, used, temp, level + 1, count);
            used[i] = false;
        }
    }
}

private static boolean isPerfectSquare(int num) {
    int sqrt = (int) Math.sqrt(num);
    return sqrt * sqrt == num;
}

public static int largestRectangleArea(int[] heights) {
    if (heights == null || heights.length == 0) {
        return 0;
    }

    int maxArea = 0;
    int n = heights.length;
    int[] left = new int[n];
    int[] right = new int[n];

    left[0] = -1;
    right[n - 1] = n;

    for (int i = 1; i < n; i++) {
        int j = i - 1;
        while (j >= 0 && heights[j] >= heights[i]) {
            j = left[j];
        }
        left[i] = j;
    }

    for (int i = n - 2; i >= 0; i--) {
        int j = i + 1;
        while (j < n && heights[j] >= heights[i]) {
            j = right[j];
        }
        right[i] = j;
    }

    for (int i = 0; i < n; i++) {
        maxArea = Math.max(maxArea, heights[i] * (right[i] - left[i] - 1));
    }

    return maxArea;
}

public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0) {
        return new int[0];
    }

    int rows = mat.length;
    int cols = mat[0].length;
    int[] result = new int[rows * cols];
    int r = 0, c = 0, d = 0;

    for (int i = 0; i < result.length; i++) {
        result[i] = mat[r][c];
        if ((r + c) % 2 == 0) { // moving up
            if (c == cols - 1) {
                r++;
            } else if (r == 0) {
                c++;
            } else {
                r--;
                c++;
            }
        } else { // moving down
            if (r == rows - 1) {
                c++;
            } else if (c == 0) {
                r++;
            } else {
                r++;
                c--;
            }
        }
    }
    return result;
}

public static int findSmallestInteger(int n) {
    char[] digits = Integer.toString(n).toCharArray();
    int length = digits.length;

    // Find the rightmost digit that is smaller than the digit next to it
    int i;
    for (i = length - 2; i >= 0; i--) {
        if (digits[i] < digits[i + 1]) {
            break;
        }
    }

    // If no such digit is found, return -1
    if (i == -1) {
        return -1;
    }

    // Find the smallest digit on the right side of the found digit that is larger than it
    int smallestIndex = i + 1;
    for (int j = i + 1; j < length; j++) {
        if (digits[j] > digits[i] && digits[j] < digits[smallestIndex]) {
            smallestIndex = j;
        }
    }

    // Swap the found digits
    char temp = digits[i];
    digits[i] = digits[smallestIndex];
    digits[smallestIndex] = temp;

    // Sort the digits after the position i in ascending order
    Arrays.sort(digits, i + 1, length);

    // Convert the character array back to an integer
    return Integer.parseInt(new String(digits));
}

public static List<String> centerSymmetricNumbers(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("The length of the center symmetric numbers must be a positive integer.");
    }

    return generateCenterSymmetricNumbers(n, n);
}

private static List<String> generateCenterSymmetricNumbers(int currentLength, int targetLength) {
    if (currentLength == 0) {
        return new ArrayList<>(Arrays.asList(""));
    }

    if (currentLength == 1) {
        return new ArrayList<>(Arrays.asList("0", "1", "8"));
    }

    List<String> prevList = generateCenterSymmetricNumbers(currentLength - 2, targetLength);
    List<String> resultList = new ArrayList<>();

    for (String s : prevList) {
        if (currentLength != targetLength) {
            resultList.add("0" + s + "0");
        }
        resultList.add("1" + s + "1");
        resultList.add("6" + s + "9");
        resultList.add("8" + s + "8");
        resultList.add("9" + s + "6");
    }

    return resultList;
}

public static boolean isBoomerang(int[][] points) {
    if (points == null || points.length != 3 || points[0].length != 2 || points[1].length != 2 || points[2].length != 2) {
        throw new IllegalArgumentException("Invalid input: points must be a 3x2 array");
    }

    // Extracting coordinates
    int x1 = points[0][0], y1 = points[0][1];
    int x2 = points[1][0], y2 = points[1][1];
    int x3 = points[2][0], y3 = points[2][1];

    // Calculate the area of the triangle formed by the points
    int area = x1 * (y2 - y3) + x2 * (y3 - y1) + x3 * (y1 - y2);

    // If the area is zero, the points are collinear and do not form a boomerang
    return area != 0;
}

public static int findNthUglyNumber(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("The index must be a positive integer.");
    }

    int[] uglyNumbers = new int[n];
    uglyNumbers[0] = 1;

    int i2 = 0, i3 = 0, i5 = 0;
    int nextMultipleOf2 = 2;
    int nextMultipleOf3 = 3;
    int nextMultipleOf5 = 5;

    for (int i = 1; i < n; i++) {
        int nextUglyNumber = Math.min(nextMultipleOf2, Math.min(nextMultipleOf3, nextMultipleOf5));
        uglyNumbers[i] = nextUglyNumber;

        if (nextUglyNumber == nextMultipleOf2) {
            i2++;
            nextMultipleOf2 = uglyNumbers[i2] * 2;
        }
        if (nextUglyNumber == nextMultipleOf3) {
            i3++;
            nextMultipleOf3 = uglyNumbers[i3] * 3;
        }
        if (nextUglyNumber == nextMultipleOf5) {
            i5++;
            nextMultipleOf5 = uglyNumbers[i5] * 5;
        }
    }

    return uglyNumbers[n - 1];
}

public static int calculateEnergy(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }

    int maxEnergy = 1;
    int currentEnergy = 1;

    for (int i = 1; i < s.length(); i++) {
        if (s.charAt(i) == s.charAt(i - 1)) {
            currentEnergy++;
        } else {
            maxEnergy = Math.max(maxEnergy, currentEnergy);
            currentEnergy = 1;
        }
    }

    return Math.max(maxEnergy, currentEnergy);
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    if (n < 1) {
        return result;
    }
    for (int i = 1; i <= 9; i++) {
        dfs(i, n, result);
    }
    return result;
}

private static void dfs(int current, int n, List<Integer> result) {
    if (current > n) {
        return;
    }
    result.add(current);
    for (int i = 0; i <= 9; i++) {
        int next = current * 10 + i;
        if (next > n) {
            return;
        }
        dfs(next, n, result);
    }
}

public static int calculateUniqueSum(int[] nums) {
    Map<Integer, Integer> counts = new HashMap<>();
    for (int num : nums) {
        counts.put(num, counts.getOrDefault(num, 0) + 1);
    }
    int sum = 0;
    for (Map.Entry<Integer, Integer> entry : counts.entrySet()) {
        if (entry.getValue() == 1) {
            sum += entry.getKey();
        }
    }
    return sum;
}

public static int minPerfectSquareSum(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("Input must be a positive integer.");
    }

    int[] dp = new int[n + 1];
    Arrays.fill(dp, Integer.MAX_VALUE);
    dp[0] = 0;

    for (int i = 1; i <= n; i++) {
        for (int j = 1; j * j <= i; j++) {
            dp[i] = Math.min(dp[i], dp[i - j * j] + 1);
        }
    }

    return dp[n];
}

public static String reverseWords(String s) {
    if (s == null || s.length() == 0) {
        return s;
    }

    String[] words = s.split(" ");
    StringBuilder result = new StringBuilder();

    for (int i = 0; i < words.length; i++) {
        String word = words[i];
        StringBuilder reversedWord = new StringBuilder(word).reverse();
        result.append(reversedWord);

        if (i < words.length - 1) {
            result.append(" ");
        }
    }

    return result.toString();
}
